//! 🧳️ Actual finite Source laws preserve typed failure data separately from a refused metadata acknowledgement.
use semio_framework_value_native_decoding::*;
use semio_framework_value_control_contract::*;
use semio_framework_value_retirement::OriginalRetirementFailure;
use std::{mem::{size_of,ManuallyDrop},sync::{Arc,atomic::{AtomicUsize,Ordering}}};
#[path="../../🧪️tests/source-bank.rs"]mod source_bank;
use source_bank::Bank;
fn law()->serde_json::Value{serde_json::from_str(include_str!("failure-data.json")).unwrap()}
trait Domain:NativeReceivingEffectError+std::fmt::Debug+From<ValueError>+Sized{
 const TAG:&'static str;
 fn full(error:&NativeReceivingFailure)->&NativeReceivingEffectFailure<Self>;
 fn message(&self)->&str;
 fn demand()->Result<RetirementDemand,ValueError>;
 fn publish<'reply>(source:&mut Option<NativeReceivingEffectOutcome<Self>>,output:&mut Option<NativeReceivingFailure>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>;
}
macro_rules! domain{($ty:ty,$tag:ident)=>{impl Domain for $ty{
 const TAG:&'static str=stringify!($tag);
 fn full(error:&NativeReceivingFailure)->&NativeReceivingEffectFailure<Self>{match error{NativeReceivingFailure::$tag(error)=>error,_=>panic!("original typed failure domain changed")}}
 fn message(&self)->&str{domain!(@message self,$tag)}
 fn demand()->Result<RetirementDemand,ValueError>{NativeReceivingEffect::<Self>::failure_transfer_demand::<OriginalReceivingPrimary>()}
 fn publish<'reply>(source:&mut Option<NativeReceivingEffectOutcome<Self>>,output:&mut Option<NativeReceivingFailure>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{NativeReceivingEffect::<Self>::take_failure_into(source,output,effect,reply)}
}};(@message $e:ident,ValueEffect)=>{$e.message.as_ref()};(@message $e:ident,RetirementEffect)=>{$e.primary().unwrap().message.as_ref()};(@message $e:ident,ReceivingEffect)=>{$e.message()};}
domain!(ValueError,ValueEffect);domain!(OriginalRetirementFailure,RetirementEffect);domain!(OriginalReceivingPrimary,ReceivingEffect);
struct Semantic<E:Domain>{source:Arc<OriginalSourceTurnIssuer>,error:ManuallyDrop<Option<E>>,calls:Arc<AtomicUsize>}
fn semantic_demand<E:Domain>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Option<E>>(),depth:1,..Default::default()}}
impl<E:Domain> OriginalEffectProducer for Semantic<E>{
 type Output=RetainedCloneStep;type Failure=E;type Context<'turn,'source>=&'turn OriginalSourceTurn where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.identity())}
 fn receive<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,E>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,E>,ValueError>where 'source:'turn{assert!(retained_clone_grant_admits(effect.grant(),semantic_demand::<E>()));assert!(effect.performed(1)?);self.calls.fetch_add(1,Ordering::SeqCst);Ok(reply.complete(Err(self.error.take().unwrap())))}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,E>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,E>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
enum Operation<'a,E:Domain>{Whole(&'a mut NativeReceivingEffect<E>,&'a mut Option<NativeReceivingEffectOutcome<E>>),Failure(&'a mut Option<NativeReceivingEffectOutcome<E>>,&'a mut Option<NativeReceivingFailure>)}
struct Context<'a,E:Domain>{turn:&'a OriginalSourceTurn,operation:Operation<'a,E>}
struct Transfer<E:Domain>{source:Arc<OriginalSourceTurnIssuer>,interrupt:bool,calls:Arc<AtomicUsize>,recovers:Arc<AtomicUsize>,domain:std::marker::PhantomData<fn()->E>}
impl<E:Domain> OriginalEffectProducer for Transfer<E>{
 type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'turn,'source>=Context<'turn,E>where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c.turn).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.turn.identity())}
 fn receive<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{match &mut c.operation{Operation::Whole(frame,output)=>frame.transfer_into(output,effect,reply),Operation::Failure(source,output)=>{self.calls.fetch_add(1,Ordering::SeqCst);let result=E::publish(source,output,effect,reply)?;if self.interrupt&&source.is_none()&&output.is_some(){self.interrupt=false;assert!(result.is_recorded());panic!("original full typed failure and metadata reply recorded before unwind")}Ok(result)}}}
 fn recover<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{self.recovers.fetch_add(1,Ordering::SeqCst);match &mut c.operation{Operation::Whole(frame,output)=>frame.transfer_into(output,effect,reply),Operation::Failure(source,output)=>E::publish(source,output,effect,reply)}}
}
fn transfer<E:Domain>(bank:&mut Bank,control:&mut NativeDecodeControl<'_>,meta:&mut NativeReceivingEffect<OriginalReceivingPrimary>,authority:&mut OriginalEffectAuthority<Transfer<E>>,operation:Operation<'_,E>,demand:RetirementDemand,work:u64)->NativeReceivingEffectPoll<OriginalReceivingPrimary>{bank.run_with_turn(control,|turn,control|{let mut context=Context{turn,operation};control.receive_original_effect(demand,work,meta,authority,|_,effect,authority,action|authority.drive(&mut context,effect,action))}).unwrap()}
fn complete(poll:NativeReceivingEffectPoll<OriginalReceivingPrimary>)->NativeReceivingEffectOutcome<OriginalReceivingPrimary>{match poll{NativeReceivingEffectPoll::Complete(turn)=>turn,NativeReceivingEffectPoll::Pending{..}=>panic!("synchronous Source should settle its actual metadata action")}}
fn native_domain<E:Domain>(){
 let law=law();assert!(law["domains"].as_array().unwrap().iter().any(|tag|tag==E::TAG));let mut bank=Bank::from_stock(&law["stock"],false);let semantic_calls=Arc::new(AtomicUsize::new(0));let transfer_calls=Arc::new(AtomicUsize::new(0));let recover_calls=Arc::new(AtomicUsize::new(0));let d=semantic_demand::<E>();let error=E::from(ValueError::new(ValueRefusalKind::InvalidValue,law["message"].as_str().unwrap().to_owned()).with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}));let pointer=error.message().as_ptr();let mut semantic=OriginalEffectAuthority::new(Semantic{source:bank.source.clone(),error:ManuallyDrop::new(Some(error)),calls:semantic_calls.clone()});let mut authority=OriginalEffectAuthority::new(Transfer::<E>{source:bank.source.clone(),interrupt:true,calls:transfer_calls.clone(),recovers:recover_calls.clone(),domain:std::marker::PhantomData});let mut observer=|_|true;let mut control=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::default();let mut meta=NativeReceivingEffect::default();let mut original=None;let mut output=None;bank.wallet.lock().unwrap().reject=true;
 let state=bank.run_with_turn(&mut control,|turn,control|{let mut context=turn;control.receive_original_effect_retained(d,1,&mut frame,&mut semantic,&mut context)}).unwrap();assert_eq!(state,NativeReceivingEffectState::Ready{work:1});bank.wallet.lock().unwrap().reject=false;let d=frame.transfer_demand().unwrap();complete(transfer(&mut bank,&mut control,&mut meta,&mut authority,Operation::Whole(&mut frame,&mut original),d,1)).result.unwrap();assert_eq!(original.as_ref().unwrap().work,0);let failure=original.as_ref().unwrap().result.as_ref().unwrap_err();assert!(failure.receiving.receipt_refusal.is_some());assert_eq!(failure.child.as_ref().unwrap().message().as_ptr(),pointer);let original_receipt=failure.receiving.receipt_refusal.as_ref().unwrap().message.as_ptr();let original_progress=failure.retained_progress();let d=E::demand().unwrap();
 output=Some(NativeReceivingFailure::Primary(ValueError::invariant("occupied caller failure slot").into()));let denied=complete(transfer(&mut bank,&mut control,&mut meta,&mut authority,Operation::Failure(&mut original,&mut output),d,1));assert!(denied.result.is_err());assert_eq!(denied.work,0);assert!(original.is_some());assert!(matches!(output.as_ref().unwrap(),NativeReceivingFailure::Primary(e)if e.message()=="occupied caller failure slot"));output.take();
 for(d,work)in[(d,0),(RetirementDemand{copy_bytes:d.copy_bytes-1,..d},1)]{let before=bank.wallet.lock().unwrap().fuel;let denied=complete(transfer(&mut bank,&mut control,&mut meta,&mut authority,Operation::Failure(&mut original,&mut output),d,work));assert_eq!(denied.result.unwrap().progress(),Default::default());assert_eq!(denied.work,0);assert!(output.is_none());assert_eq!(original.as_ref().unwrap().result.as_ref().unwrap_err().child.as_ref().unwrap().message().as_ptr(),pointer);assert_eq!(bank.wallet.lock().unwrap().fuel,before);}
 let calls=transfer_calls.load(Ordering::SeqCst);bank.wallet.lock().unwrap().reject=true;let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||transfer(&mut bank,&mut control,&mut meta,&mut authority,Operation::Failure(&mut original,&mut output),d,1)));assert!(interrupted.is_err());assert!(meta.has_pending_recovery()&&authority.has_pending_action());assert!(original.is_none()&&output.is_some());let acknowledgement=complete(transfer(&mut bank,&mut control,&mut meta,&mut authority,Operation::Failure(&mut original,&mut output),d,1));assert_eq!(acknowledgement.work,1);let acknowledgement=acknowledgement.result.unwrap_err();assert!(acknowledgement.receiving.receipt_refusal.is_some());assert!(acknowledgement.child.is_none());assert_eq!(acknowledgement.retained_progress().copied_bytes,d.copy_bytes);let data=E::full(output.as_ref().unwrap());assert_eq!(data.child.as_ref().unwrap().message().as_ptr(),pointer);assert_eq!(data.receiving.receipt_refusal.as_ref().unwrap().message.as_ptr(),original_receipt);assert_eq!(data.retained_progress(),original_progress);assert_eq!(transfer_calls.load(Ordering::SeqCst),calls+1);assert_eq!(recover_calls.load(Ordering::SeqCst),0);assert_eq!(semantic_calls.load(Ordering::SeqCst),1);assert_eq!(control.actual_work(),3);assert_eq!(law["stock"]["fuel"].as_u64().unwrap()as u128-bank.wallet.lock().unwrap().fuel,3);assert!(!meta.has_pending_recovery());assert!(semantic.into_producer().is_ok());assert!(authority.into_producer().is_ok());
}
#[test]fn actual_value_failure_data_and_its_refused_acknowledgement_remain_independent(){native_domain::<ValueError>()}
#[test]fn actual_retirement_failure_data_and_its_refused_acknowledgement_remain_independent(){native_domain::<OriginalRetirementFailure>()}
#[test]fn actual_receiving_failure_data_and_its_refused_acknowledgement_remain_independent(){native_domain::<OriginalReceivingPrimary>()}
